:root:not(.dark) {
  --success: #00723F;
  --success-foreground: #00572F;
  --info: #0068A0;
  --info-foreground: #004F7C;
  --guest: #7D5800;
  --guest-foreground: #7D5800;
  --chart-1: #006B61;
  --chart-2: #7D5800;
  --chart-3: #715C2F;
  --chart-4: #00723F;
  --chart-5: #716300;
  --chart-6: #006F6C;
  --m3-primary: #006B61;
  --m3-on-primary: #E2FFF9;
  --m3-primary-container: #6DF2E1;
  --m3-on-primary-container: #005950;
  --m3-secondary-container: #FCDFA6;
  --m3-on-secondary-container: #634F23;
  --m3-tertiary: #7D5800;
  --m3-surface-container: #C8F7F5;
  --m3-surface-container-high: #BCF2F1;
  --m3-outline: #488484;
  --m3-outline-variant: #80BDBB;
}

:root.dark, .dark {
  --success: #61D78F;
  --success-foreground: #7EF4A9;
  --info: #88C7FF;
  --info-foreground: #C2E0FF;
  --guest: #FFC967;
  --guest-foreground: #FFC967;
  --chart-1: #98ECDF;
  --chart-2: #FFC967;
  --chart-3: #D8C4A0;
  --chart-4: #61D78F;
  --chart-5: #DBC100;
  --chart-6: #46D5CF;
  --m3-primary: #98ECDF;
  --m3-on-primary: #005950;
  --m3-primary-container: #006D63;
  --m3-on-primary-container: #F1FFFB;
  --m3-secondary-container: #2F240C;
  --m3-on-secondary-container: #B4A280;
  --m3-tertiary: #FFC967;
  --m3-surface-container: #001E1D;
  --m3-surface-container-high: #002424;
  --m3-outline: #537D7C;
  --m3-outline-variant: #254E4E;
}

/* Material 3 Expressive (m3.material.io / androidx v14.1.0 + v0.14.0) shape, spring motion, and surface polish */

:root {
  /* Master T3 Code radius and drawer motion tokens */
  --radius: 1rem;
  --control-radius: 16px;
  --ease-drawer: var(--m3-motion-default-spatial);

  /* M3 Expressive Shape scale (m3.material.io/styles/shape/corner-radius-scale, ShapeTokens.kt v14.1.0) */
  --m3-shape-xs: 4px;
  --m3-shape-sm: 8px;
  --m3-shape-md: 12px;
  --m3-shape-lg: 16px;
  --m3-shape-lg-inc: 20px;
  --m3-shape-xl: 28px;
  --m3-shape-xl-inc: 32px;
  --m3-shape-full: 9999px;

  /* Finite pill radii matched to T3 Code control heights for artifact-free corner morphing */
  --m3-pill-control: 16px;
  --m3-pill-row: 18px;

  /* M3 Expressive Motion Physics (m3.material.io/styles/motion/overview/specs, ExpressiveMotionTokens.kt v0.14.0)
   * Analytical spring ODE samples in linear() (Chromium 113+):
   *   fast-spatial:    damping=0.6, stiffness=800  (web fallback: cubic-bezier(0.42, 1.67, 0.21, 0.90) 350ms)
   *   default-spatial: damping=0.8, stiffness=380  (web fallback: cubic-bezier(0.38, 1.21, 0.22, 1.00) 500ms)
   *   slow-spatial:    damping=0.8, stiffness=200  (web fallback: cubic-bezier(0.39, 1.29, 0.35, 0.98) 650ms)
   *   fast-effects:    damping=1.0, stiffness=3800 (web fallback: cubic-bezier(0.31, 0.94, 0.34, 1.00) 150ms)
   *   default-effects: damping=1.0, stiffness=1600 (web fallback: cubic-bezier(0.34, 0.80, 0.34, 1.00) 200ms)
   *   slow-effects:    damping=1.0, stiffness=800  (web fallback: cubic-bezier(0.34, 0.88, 0.34, 1.00) 300ms)
   */
  --m3-motion-fast-spatial-duration: 359ms;
  --m3-motion-fast-spatial: linear(0, 0.075, 0.2481, 0.4562, 0.6567, 0.8248, 0.9503, 1.0326, 1.0777, 1.0941, 1.0909, 1.0764, 1.0572, 1.0377, 1.0207, 1.0076, 0.9987, 0.9935, 0.9913, 0.9912, 0.9923, 0.994, 0.9959, 0.9976, 1);
  --m3-motion-default-spatial-duration: 434ms;
  --m3-motion-default-spatial: linear(0, 0.0514, 0.1698, 0.3152, 0.4623, 0.5966, 0.7108, 0.803, 0.874, 0.9262, 0.9629, 0.9872, 1.0023, 1.0106, 1.0144, 1.0151, 1.0142, 1.0123, 1.0101, 1.0078, 1.0058, 1.0042, 1.0028, 1.0018, 1);
  --m3-motion-slow-spatial-duration: 599ms;
  --m3-motion-slow-spatial: linear(0, 0.0515, 0.1702, 0.3158, 0.4631, 0.5974, 0.7116, 0.8038, 0.8746, 0.9267, 0.9633, 0.9875, 1.0024, 1.0107, 1.0144, 1.0151, 1.0141, 1.0122, 1.01, 1.0078, 1.0058, 1.0041, 1.0028, 1.0018, 1);
  --m3-motion-fast-effects-duration: 149ms;
  --m3-motion-fast-effects: linear(0, 0.057, 0.1788, 0.3185, 0.4524, 0.5701, 0.6683, 0.7475, 0.8099, 0.8581, 0.8949, 0.9226, 0.9434, 0.9587, 0.97, 0.9783, 0.9844, 0.9888, 0.992, 0.9943, 0.9959, 0.9971, 0.9979, 0.9985, 1);
  --m3-motion-default-effects-duration: 230ms;
  --m3-motion-default-effects: linear(0, 0.0571, 0.1793, 0.3192, 0.4533, 0.571, 0.6691, 0.7483, 0.8106, 0.8587, 0.8954, 0.9231, 0.9437, 0.959, 0.9703, 0.9785, 0.9845, 0.9889, 0.992, 0.9943, 0.9959, 0.9971, 0.9979, 0.9985, 1);
  --m3-motion-slow-effects-duration: 326ms;
  --m3-motion-slow-effects: linear(0, 0.0574, 0.1799, 0.3202, 0.4544, 0.5722, 0.6703, 0.7494, 0.8116, 0.8596, 0.8961, 0.9237, 0.9442, 0.9594, 0.9706, 0.9788, 0.9847, 0.989, 0.9921, 0.9944, 0.996, 0.9972, 0.998, 0.9986, 1);
}

/* Interactive buttons, icon buttons, composer controls, and toolbar controls.
 * Per M3 Expressive Button.kt / IconButton.kt:
 *   - Hover uses state-layer color transition (FastEffects), never scale or shape morph.
 *   - Pressed morphs round -> CornerSmall (8px) using DefaultEffects (critically damped, zero bounce).
 *   - Toggled or open menu/popover triggers morph round -> CornerMedium (12px); bare tooltip
 *     [data-popup-open] without [aria-haspopup] is excluded so hovering a tooltip never morphs shape.
 */
[data-slot="button"],
[data-chat-composer-form] button,
[data-chat-header] button,
[data-toolbar-control],
[data-slot="menu-trigger"],
button[data-slot="combobox-trigger"],
button[data-slot="popover-trigger"],
[data-thread-details-panel] :is(button, a),
[data-slot="toggle"] {
  border-radius: var(--m3-btn-radius, var(--m3-pill-control)) !important;
  font-weight: 550;
  transition:
    border-radius var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    border-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-chat-composer-transition-actions] button {
  --m3-btn-radius: var(--m3-pill-row);
}

[data-slot="button"]::before {
  border-radius: inherit !important;
}

:is(
  [data-slot="button"],
  [data-chat-composer-form] button,
  [data-chat-header] button,
  [data-toolbar-control],
  [data-slot="menu-trigger"],
  button[data-slot="combobox-trigger"],
  button[data-slot="popover-trigger"],
  [data-thread-details-panel] :is(button, a),
  [data-slot="toggle"]
):not(:disabled):is([aria-expanded="true"], [aria-pressed="true"], [data-pressed], [aria-haspopup][data-popup-open]) {
  border-radius: var(--m3-shape-md) !important;
}

:is(
  [data-slot="button"],
  [data-chat-composer-form] button,
  [data-chat-header] button,
  [data-toolbar-control],
  [data-slot="menu-trigger"],
  button[data-slot="combobox-trigger"],
  button[data-slot="popover-trigger"],
  [data-thread-details-panel] :is(button, a),
  [data-slot="toggle"]
):not(:disabled):active {
  border-radius: var(--m3-shape-sm) !important;
  scale: 1 !important;
}

/* Thread details select & split rows (SplitButtonXSmallTokens.kt: 16px outer pill, 4px inner seam, unified 8px press / 12px open) */
[data-thread-details-panel] [data-slot="select-label"] {
  border-start-start-radius: inherit !important;
  border-end-start-radius: inherit !important;
  border-start-end-radius: var(--m3-shape-xs) !important;
  border-end-end-radius: var(--m3-shape-xs) !important;
}

[data-thread-details-panel] [data-slot="select-icon"] {
  border-start-start-radius: var(--m3-shape-xs) !important;
  border-end-start-radius: var(--m3-shape-xs) !important;
  border-start-end-radius: inherit !important;
  border-end-end-radius: inherit !important;
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button) {
  border-radius: var(--m3-pill-control) !important;
  transition:
    border-radius var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button):has(> :is(button, a):is([aria-expanded="true"], [aria-haspopup][data-popup-open])) {
  border-radius: var(--m3-shape-md) !important;
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button):has(> :is(button, a):not(:disabled):active) {
  border-radius: var(--m3-shape-sm) !important;
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button) > :is(button, a):first-child {
  border-start-start-radius: inherit !important;
  border-end-start-radius: inherit !important;
  border-start-end-radius: var(--m3-shape-xs) !important;
  border-end-end-radius: var(--m3-shape-xs) !important;
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button) > button:last-child {
  border-start-start-radius: var(--m3-shape-xs) !important;
  border-end-start-radius: var(--m3-shape-xs) !important;
  border-start-end-radius: inherit !important;
  border-end-end-radius: inherit !important;
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button) > button:last-child:is([aria-expanded="true"], [aria-haspopup][data-popup-open]) {
  border-start-start-radius: var(--m3-shape-md) !important;
  border-end-start-radius: var(--m3-shape-md) !important;
  border-start-end-radius: inherit !important;
  border-end-end-radius: inherit !important;
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button) > :is(button, a):first-child:not(:disabled):active {
  border-start-start-radius: inherit !important;
  border-end-start-radius: inherit !important;
  border-start-end-radius: var(--m3-shape-sm) !important;
  border-end-end-radius: var(--m3-shape-sm) !important;
  scale: 1 !important;
}

[data-thread-details-panel] div:has(> :is(button, a) + span[aria-hidden="true"] + button) > button:last-child:not(:disabled):active {
  border-start-start-radius: var(--m3-shape-sm) !important;
  border-end-start-radius: var(--m3-shape-sm) !important;
  border-start-end-radius: inherit !important;
  border-end-end-radius: inherit !important;
  scale: 1 !important;
}

/* Connected toggle groups (ConnectedButtonGroupSmallTokens.kt, m3.material.io/components/button-groups/specs) */
[data-slot="toggle"]::before {
  border-radius: inherit !important;
}

[data-slot="toggle-group"][data-variant="segmented"] {
  border-radius: var(--m3-pill-row) !important;
  gap: 2px;
}

[data-slot="toggle-group"]:not([data-orientation="vertical"]) > [data-slot="toggle"] {
  border-radius: var(--m3-shape-sm) !important;
}

[data-slot="toggle-group"]:not([data-orientation="vertical"]) > [data-slot="toggle"]:first-of-type {
  border-start-start-radius: var(--m3-pill-control) !important;
  border-end-start-radius: var(--m3-pill-control) !important;
}

[data-slot="toggle-group"]:not([data-orientation="vertical"]) > [data-slot="toggle"]:last-of-type {
  border-start-end-radius: var(--m3-pill-control) !important;
  border-end-end-radius: var(--m3-pill-control) !important;
}

[data-slot="toggle-group"][data-orientation="vertical"] > [data-slot="toggle"] {
  border-radius: var(--m3-shape-sm) !important;
}

[data-slot="toggle-group"][data-orientation="vertical"] > [data-slot="toggle"]:first-of-type {
  border-start-start-radius: var(--m3-pill-control) !important;
  border-start-end-radius: var(--m3-pill-control) !important;
}

[data-slot="toggle-group"][data-orientation="vertical"] > [data-slot="toggle"]:last-of-type {
  border-end-start-radius: var(--m3-pill-control) !important;
  border-end-end-radius: var(--m3-pill-control) !important;
}

[data-slot="toggle-group"]:not([data-orientation="vertical"]) > [data-slot="toggle"]:is([data-pressed], [aria-pressed="true"]),
[data-slot="toggle-group"][data-orientation="vertical"] > [data-slot="toggle"]:is([data-pressed], [aria-pressed="true"]) {
  border-radius: var(--m3-pill-control) !important;
}

[data-slot="toggle-group"]:not([data-orientation="vertical"]) > [data-slot="toggle"]:not(:disabled):active,
[data-slot="toggle-group"][data-orientation="vertical"] > [data-slot="toggle"]:not(:disabled):active {
  border-radius: var(--m3-shape-xs) !important;
  scale: 1 !important;
}

/* Switches (SwitchTokens.kt: 16dp unselected -> 24dp selected -> 28dp pressed, FastSpatial motion) */
[data-slot="switch"] {
  border-radius: var(--m3-shape-full) !important;
  transition:
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    border-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="switch-thumb"] {
  border-radius: var(--m3-shape-full) !important;
  transition:
    translate var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    scale var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"] {
  scale: 0.72;
}

[data-slot="switch"][data-checked] [data-slot="switch-thumb"] {
  scale: 1;
}

[data-slot="switch"]:not([data-disabled]):active [data-slot="switch-thumb"] {
  scale: 1.12 !important;
}

/* Text inputs and selects */
[data-slot="input"] {
  border-radius: var(--m3-shape-md) !important;
  transition:
    border-color var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    box-shadow var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    background-color var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects);
}

[data-slot="input"]:focus,
[data-slot="input"]:focus-visible {
  border-color: var(--m3-primary) !important;
  box-shadow: 0 0 0 2px color-mix(in oklab, var(--m3-primary) 30%, transparent);
  outline: none;
}

[data-slot="select-trigger"] {
  border-radius: var(--m3-pill-control) !important;
  transition:
    border-radius var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    border-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="select-trigger"]::before {
  border-radius: inherit !important;
}

[data-slot="select-trigger"]:is([data-popup-open], [aria-expanded="true"]) {
  border-radius: var(--m3-shape-md) !important;
}

[data-slot="select-trigger"]:not(:disabled):active {
  border-radius: var(--m3-shape-sm) !important;
}

[data-slot="select-trigger"]:focus,
[data-slot="select-trigger"]:focus-visible {
  border-color: var(--m3-primary) !important;
  box-shadow: 0 0 0 2px color-mix(in oklab, var(--m3-primary) 30%, transparent);
  outline: none;
}

/* Sidebar, folder headers, and thread rows (NavigationDrawerTokens.kt: pill active indicator, no hover shift) */
[data-slot="sidebar"],
[data-slot="sidebar-inner"] {
  border-color: color-mix(in oklab, var(--m3-outline-variant) 55%, transparent);
}

[data-thread-item] [role="button"],
[data-thread-item] [data-sidebar-row],
[data-sidebar-row] {
  border-radius: var(--m3-pill-row) !important;
  transition:
    border-radius var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

:is([data-thread-item] [role="button"], [data-thread-item] [data-sidebar-row], [data-sidebar-row]):active {
  border-radius: var(--m3-shape-md) !important;
}

:is([data-thread-item] [role="button"], [data-thread-item] [data-sidebar-row], [data-sidebar-row]):is([aria-current="page"], [data-active="true"]) {
  font-weight: 600;
}

[data-slot="project-monogram"],
[data-slot="project-monogram"] > svg {
  border-radius: var(--m3-shape-md) !important;
}

/* Header and conversation surface */
[data-chat-header] {
  border-bottom-color: color-mix(in oklab, var(--m3-outline-variant) 55%, transparent);
  font-variation-settings: "opsz" 24, "wght" 580, "ROND" 100;
}

[data-workspace-area="conversation"],
.messages-timeline-scroll {
  scroll-behavior: smooth;
}

[data-user-message-bubble] {
  border-radius: 26px 26px 6px 26px !important;
  border-color: transparent !important;
  box-shadow: 0 1px 3px color-mix(in oklab, var(--m3-primary) 14%, transparent);
}

[data-timeline-row-kind="work"] button {
  border-radius: var(--m3-shape-md) !important;
  transition:
    border-radius var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-timeline-row-kind="work"] button:active {
  border-radius: var(--m3-shape-sm) !important;
  scale: 1 !important;
}

/* Composer shell, host, and main glass surface (steady CornerExtraLarge 28px; focus outline uses DefaultEffects) */
[data-slot="composer-shell"],
[data-slot="composer-shell"]::before,
[data-slot="composer-host"],
[data-slot="composer-host"]::before,
[data-slot="composer-host"]::after,
[data-chat-composer-main-surface],
[data-chat-composer-main-surface]::after {
  border-radius: var(--m3-shape-xl) !important;
  transition:
    border-color var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    box-shadow var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    background-color var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects);
}

[data-slot="composer-host"]:focus-within {
  border-color: color-mix(in oklab, var(--m3-primary) 55%, transparent);
  box-shadow: 0 0 0 2px color-mix(in oklab, var(--m3-primary) 48%, transparent);
}

.composer-tiptap {
  caret-color: var(--m3-primary);
}

/* Markdown typography and blocks */
.chat-markdown h1,
.chat-markdown h2,
.chat-markdown h3 {
  letter-spacing: -0.02em;
  font-weight: 620;
  font-variation-settings: "opsz" 28, "wght" 620, "ROND" 100;
}

.chat-markdown a {
  color: var(--m3-primary);
  text-underline-offset: 3px;
}

.chat-markdown blockquote {
  border-left: 3px solid var(--m3-tertiary);
  border-radius: 0 12px 12px 0;
  background-color: color-mix(in oklab, var(--m3-surface-container) 65%, transparent);
  padding-block: 0.4rem;
  padding-inline: 0.85rem;
}

.chat-markdown-codeblock {
  border-radius: var(--m3-shape-lg-inc) !important;
}

/* Dialogs & alert dialogs (DialogTokens.kt: 28dp container, DefaultSpatial enter / FastEffects exit) */
[data-slot="dialog-popup"],
[data-slot="alert-dialog-popup"] {
  border-radius: var(--m3-shape-xl) !important;
  transition:
    scale var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial),
    translate var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

:is([data-slot="dialog-popup"], [data-slot="alert-dialog-popup"]):is([data-starting-style], [data-ending-style]) {
  scale: 0.92;
  translate: 0 12px;
  opacity: 0;
}

:is([data-slot="dialog-popup"], [data-slot="alert-dialog-popup"])[data-ending-style] {
  transition:
    scale var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    translate var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="dialog-backdrop"],
[data-slot="alert-dialog-backdrop"],
[data-slot="sheet-backdrop"] {
  transition: opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

/* Menus & selects (SegmentedMenuTokens.kt: 16dp container, Menu.kt: FastSpatial scale + FastEffects opacity) */
[data-slot="menu-popup"],
[data-slot="select-popup"] {
  border-radius: var(--m3-shape-lg) !important;
  transition:
    scale var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="select-popup"] > div {
  border-radius: inherit !important;
}

:is([data-slot="menu-popup"], [data-slot="select-popup"]):is([data-starting-style], [data-ending-style]) {
  scale: 0.86;
  opacity: 0;
}

:is([data-slot="menu-popup"], [data-slot="select-popup"])[data-ending-style] {
  transition:
    scale var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

/* Popovers (FastSpatial scale, DefaultSpatial resize, FastEffects opacity/exit, Base UI instant preserved) */
[data-slot="popover-popup"]:not(.rounded-none) {
  border-radius: var(--m3-shape-lg-inc) !important;
  transition:
    scale var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    width var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial),
    height var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial);
}

[data-slot="popover-popup"]:not(.rounded-none):is([data-starting-style], [data-ending-style]) {
  scale: 0.9;
  opacity: 0;
}

[data-slot="popover-popup"]:not(.rounded-none)[data-ending-style] {
  transition:
    scale var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="popover-popup"][data-instant] {
  transition-duration: 0ms;
}

/* Tooltips (Tooltip.kt: FastSpatial scale + FastEffects opacity, Base UI instant handoff preserved) */
[data-slot="tooltip-popup"] {
  border-radius: var(--m3-shape-sm) !important;
  transition:
    scale var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="tooltip-popup"]:is([data-starting-style], [data-ending-style]) {
  scale: 0.9;
  opacity: 0;
}

[data-slot="tooltip-popup"][data-ending-style] {
  transition:
    scale var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="tooltip-popup"][data-instant] {
  transition-duration: 0ms;
}

[data-slot="dialog-popup"]::before,
[data-slot="alert-dialog-popup"]::before,
[data-slot="popover-popup"]:not(.rounded-none)::before,
[data-slot="menu-popup"]::before,
[data-slot="select-popup"]::before,
[data-slot="tooltip-popup"]::before {
  border-radius: inherit !important;
}

/* App panels (sidebar & terminal drawer), collapsibles, sheets, and toasts */
[data-panel-animations="true"] [data-slot="sidebar"][data-state="expanded"] :is([data-slot="sidebar-gap"], [data-slot="sidebar-container"]) {
  transition-duration: var(--m3-motion-default-spatial-duration);
  transition-timing-function: var(--m3-motion-default-spatial);
}

[data-panel-animations="true"] [data-slot="sidebar"][data-state="collapsed"] :is([data-slot="sidebar-gap"], [data-slot="sidebar-container"]) {
  transition-duration: var(--m3-motion-default-effects-duration);
  transition-timing-function: var(--m3-motion-default-effects);
}

[data-panel-animations="true"] div:has(> div > [data-thread-terminal-drawer]) {
  transition-duration: var(--m3-motion-default-spatial-duration);
  transition-timing-function: var(--m3-motion-default-spatial);
}

[data-slot="collapsible-panel"] {
  transition-duration: var(--m3-motion-default-spatial-duration);
  transition-timing-function: var(--m3-motion-default-spatial);
}

[data-slot="collapsible-panel"][data-ending-style] {
  transition-duration: var(--m3-motion-default-effects-duration);
  transition-timing-function: var(--m3-motion-default-effects);
}

[data-slot="sheet-popup"] {
  transition:
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    translate var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial),
    transform var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial);
}

[data-slot="sheet-popup"][data-ending-style] {
  transition:
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    translate var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    transform var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="toast-viewport"] > * {
  border-radius: var(--m3-shape-lg) !important;
  transition:
    transform var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    height var(--m3-motion-default-spatial-duration) var(--m3-motion-default-spatial);
}

[data-slot="toast-viewport"] > *[data-ending-style] {
  transition:
    transform var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    height var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="toast-popup"] {
  border-radius: var(--m3-shape-md) !important;
  transition:
    scale var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="toast-popup"]:is([data-starting-style], [data-ending-style]) {
  scale: 0.88;
  opacity: 0;
}

[data-slot="toast-popup"][data-ending-style] {
  transition:
    scale var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

/* Menu & select items (concentric 8px -> 12px inside 16px container with 4px padding; FastSpatial morph per Menu.kt) */
[data-slot="menu-item"],
[data-slot="select-item"],
[data-slot="menu-radio-item"],
[data-slot="menu-checkbox-item"],
[data-slot="menu-sub-trigger"] {
  border-radius: var(--m3-shape-sm) !important;
  transition:
    border-radius var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects),
    color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

:is(
  [data-slot="menu-item"],
  [data-slot="select-item"],
  [data-slot="menu-radio-item"],
  [data-slot="menu-checkbox-item"],
  [data-slot="menu-sub-trigger"]
):is([data-highlighted], [data-checked], [data-selected]) {
  border-radius: var(--m3-shape-md) !important;
}

/* Cards and terminal drawer (ExpandedListTokens.kt: CornerLarge 16dp) */
[data-thread-details-card],
[data-settings-page-scroll] [data-slot="card"] {
  border-radius: var(--m3-shape-lg) !important;
}

[data-thread-terminal-drawer] {
  border-top-left-radius: var(--m3-shape-lg-inc);
  border-top-right-radius: var(--m3-shape-lg-inc);
}

/* Expressive settings sliders (SliderTokens.kt: 4px vertical bar handle, 12px pill track, FastSpatial) */
.settings-slider {
  --settings-slider-fill-offset: 0.125rem;
  height: 1.75rem;
}

.settings-slider::-webkit-slider-runnable-track {
  height: 0.75rem;
  border-radius: var(--m3-shape-full);
  background: linear-gradient(
    to right,
    var(--m3-primary) 0 var(--settings-slider-fill-position),
    var(--m3-surface-container-high) var(--settings-slider-fill-position) 100%
  );
  box-shadow: none;
}

.settings-slider::-moz-range-track {
  height: 0.75rem;
  border-radius: var(--m3-shape-full);
  background: var(--m3-surface-container-high);
  box-shadow: none;
}

.settings-slider::-moz-range-progress {
  height: 0.75rem;
  border-radius: var(--m3-shape-full);
  background: var(--m3-primary);
}

.settings-slider::-webkit-slider-thumb {
  width: 4px;
  height: 24px;
  margin-top: -6px;
  border: none;
  border-radius: var(--m3-shape-full);
  background: var(--m3-primary);
  box-shadow: 0 0 0 3px var(--background);
  transition:
    transform var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

.settings-slider::-moz-range-thumb {
  width: 4px;
  height: 24px;
  border: none;
  border-radius: var(--m3-shape-full);
  background: var(--m3-primary);
  box-shadow: 0 0 0 3px var(--background);
  transition:
    transform var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

.settings-slider:hover::-webkit-slider-thumb,
.settings-slider:hover::-moz-range-thumb {
  transform: scaleY(1.06);
  box-shadow: 0 0 0 3px var(--background);
}

.settings-slider:active::-webkit-slider-thumb,
.settings-slider:active::-moz-range-thumb {
  transform: scaleX(0.65) scaleY(1.1);
}

.settings-slider:focus-visible::-webkit-slider-thumb,
.settings-slider:focus-visible::-moz-range-thumb {
  box-shadow:
    0 0 0 2px var(--background),
    0 0 0 4px var(--m3-primary);
}

/* Checkboxes, radio indicators, pill badges, and composer banners (Checkbox.kt, RadioButton.kt) */
[data-slot="checkbox"] {
  border-radius: 5px !important;
  transition:
    border-color var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    background-color var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="checkbox-indicator"] {
  border-radius: inherit !important;
  transition:
    scale var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial),
    opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="radio"] {
  transition:
    border-color var(--m3-motion-default-effects-duration) var(--m3-motion-default-effects),
    box-shadow var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="radio-indicator"]::before {
  transition: scale var(--m3-motion-fast-spatial-duration) var(--m3-motion-fast-spatial);
}

@starting-style {
  [data-slot="checkbox-indicator"] {
    scale: 0.6;
    opacity: 0;
  }

  [data-slot="radio-indicator"]::before {
    scale: 0;
  }
}

[data-slot="badge"] {
  border-radius: var(--m3-shape-full) !important;
}

[data-slot="composer-banner-attachment"],
[data-slot="composer-banner"] {
  transition: opacity var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

/* Icons and text selection */
svg.lucide {
  stroke-linecap: round;
  stroke-linejoin: round;
}

::selection {
  background: var(--m3-primary-container);
  color: var(--m3-on-primary-container);
}

/* Scrollbars */
[data-slot="scroll-area-scrollbar"] {
  border-radius: var(--m3-shape-full);
}

[data-slot="scroll-area-thumb"] {
  border-radius: var(--m3-shape-full) !important;
  background-color: color-mix(in oklab, var(--m3-outline) 50%, transparent);
  transition: background-color var(--m3-motion-fast-effects-duration) var(--m3-motion-fast-effects);
}

[data-slot="scroll-area-thumb"]:hover,
[data-slot="scroll-area-scrollbar"]:hover [data-slot="scroll-area-thumb"] {
  background-color: color-mix(in oklab, var(--m3-outline) 80%, transparent);
}

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  border-radius: var(--m3-shape-full);
  background: color-mix(in oklab, var(--m3-outline) 50%, transparent);
}

::-webkit-scrollbar-thumb:hover {
  background: color-mix(in oklab, var(--m3-outline) 80%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --m3-motion-fast-spatial-duration: 0ms;
    --m3-motion-default-spatial-duration: 0ms;
    --m3-motion-slow-spatial-duration: 0ms;
    --m3-motion-fast-effects-duration: 0ms;
    --m3-motion-default-effects-duration: 0ms;
    --m3-motion-slow-effects-duration: 0ms;
  }
}
